import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

// C[row] = sum_k A[row, k] * B[k]
// One thread block per output row. Threads accumulate a strided partial
// dot product using vectorized float4 loads (with a scalar tail path for
// any partial chunk), then reduce across the block via warp shuffles and
// shared memory.
.visible .entry matvec_kernel(
    .param .u64 pA,
    .param .u64 pB,
    .param .u64 pC,
    .param .u32 pM,
    .param .u32 pK
)
{
    .reg .pred  %p<4>;
    .reg .b32   %r<16>;
    .reg .b64   %rd<16>;
    .reg .f32   %f<16>;

    .shared .align 4 .b8 warp_sums[128];

    ld.param.u64 %rd0, [pA];            // A base
    ld.param.u64 %rd1, [pB];            // B base
    ld.param.u64 %rd2, [pC];            // C base
    ld.param.u32 %r0,  [pM];            // M
    ld.param.u32 %r1,  [pK];            // K

    mov.u32 %r2, %ctaid.x;              // row index
    setp.ge.u32 %p0, %r2, %r0;
    @%p0 bra EXIT;                      // bounds check on row

    mov.u32 %r3, %tid.x;                // thread id

    mul.wide.u32 %rd3, %r2, %r1;        // row * K (elements)
    shl.b64 %rd3, %rd3, 2;              // row * K * 4 (bytes)
    add.u64 %rd4, %rd0, %rd3;           // &A[row][0]

    shl.b32 %r4, %r3, 2;                // idx = tid * 4
    mov.u32 %r5, %ntid.x;
    shl.b32 %r5, %r5, 2;                // stride = blockDim.x * 4

    mov.f32 %f0, 0f00000000;
    mov.f32 %f1, 0f00000000;
    mov.f32 %f2, 0f00000000;
    mov.f32 %f3, 0f00000000;

VEC_LOOP:
    setp.ge.u32 %p0, %r4, %r1;          // idx >= K -> done
    @%p0 bra COMBINE;
    add.u32 %r6, %r4, 4;
    setp.gt.u32 %p1, %r6, %r1;          // idx+4 > K -> scalar tail
    @%p1 bra TAIL_LOOP;

    mul.wide.u32 %rd5, %r4, 4;          // byte offset
    add.u64 %rd6, %rd4, %rd5;           // &A[row][idx]
    add.u64 %rd7, %rd1, %rd5;           // &B[idx]
    ld.global.v4.f32 {%f4,%f5,%f6,%f7},  [%rd6];
    ld.global.v4.f32 {%f8,%f9,%f10,%f11}, [%rd7];
    fma.rn.f32 %f0, %f4, %f8,  %f0;
    fma.rn.f32 %f1, %f5, %f9,  %f1;
    fma.rn.f32 %f2, %f6, %f10, %f2;
    fma.rn.f32 %f3, %f7, %f11, %f3;
    add.u32 %r4, %r4, %r5;
    bra VEC_LOOP;

TAIL_LOOP:
    setp.ge.u32 %p0, %r4, %r1;
    @%p0 bra COMBINE;
    mul.wide.u32 %rd5, %r4, 4;
    add.u64 %rd6, %rd4, %rd5;
    add.u64 %rd7, %rd1, %rd5;
    ld.global.f32 %f4, [%rd6];
    ld.global.f32 %f8, [%rd7];
    fma.rn.f32 %f0, %f4, %f8, %f0;
    add.u32 %r4, %r4, 1;
    bra TAIL_LOOP;

COMBINE:
    add.f32 %f0, %f0, %f1;
    add.f32 %f2, %f2, %f3;
    add.f32 %f0, %f0, %f2;

    // Intra-warp reduction (all warps execute this).
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 16, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 8, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 4, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 2, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 1, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;

    and.b32 %r7, %r3, 31;               // lane id
    shr.u32 %r8, %r3, 5;                // warp id

    setp.eq.u32 %p0, %r7, 0;
    @!%p0 bra AFTER_STORE;
    mov.u64 %rd8, warp_sums;
    mul.wide.u32 %rd9, %r8, 4;
    add.u64 %rd8, %rd8, %rd9;
    st.shared.f32 [%rd8], %f0;
AFTER_STORE:
    bar.sync 0;

    // Only warp 0 reduces the per-warp partial sums.
    setp.ne.u32 %p0, %r8, 0;
    @%p0 bra EXIT;

    mov.u32 %r9, %ntid.x;
    shr.u32 %r9, %r9, 5;                // number of warps
    mov.f32 %f0, 0f00000000;
    setp.lt.u32 %p1, %r7, %r9;
    @!%p1 bra FINAL_REDUCE;
    mov.u64 %rd8, warp_sums;
    mul.wide.u32 %rd9, %r7, 4;
    add.u64 %rd8, %rd8, %rd9;
    ld.shared.f32 %f0, [%rd8];

FINAL_REDUCE:
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 16, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 8, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 4, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 2, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;
    mov.b32 %r10, %f0;
    shfl.sync.down.b32 %r11, %r10, 1, 0x1f, 0xffffffff;
    mov.b32 %f12, %r11;
    add.f32 %f0, %f0, %f12;

    setp.ne.u32 %p0, %r7, 0;
    @%p0 bra EXIT;
    mul.wide.u32 %rd10, %r2, 4;
    add.u64 %rd11, %rd2, %rd10;
    st.global.f32 [%rd11], %f0;

EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matvec_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M, K = A.shape
        C = torch.empty((M, 1), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        module.launch(
            "matvec_kernel",
            grid=(M, 1, 1),
            block=(256, 1, 1),
            arguments=[A, B, C, u32(M), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

